import "core-js/modules/es.array.push.js";
import { ListScheduledGames } from "@/mixins/ListScheduledGames";
import DeleteScheduledGameDialog from "./DeleteScheduledGameDialog.vue";
import SnackBar from "../SnackBar.vue";
export default {
  mixins: [ListScheduledGames],
  components: {
    DeleteScheduledGameDialog,
    SnackBar
  },
  data: () => ({
    windowHeight: 0,
    currentPage: 1,
    itemsPerPage: 15,
    loading: false,
    DialogDeleteScheduledGame: false,
    SnackBarComponent: {},
    ListScheduledGames: [],
    TableHeaders: [{
      title: "Category",
      value: "category_name"
    }, {
      title: "Scheduled On",
      value: "game_scheduled_time"
    }, {
      title: "Frequency",
      value: "reccuring_schedule"
    }, {
      title: "Action",
      value: "action"
    }]
  }),
  async mounted() {
    this.windowHeight = window.innerHeight - 240;
    await this.ListScheduledGamesMethod();
  },
  computed: {
    totalItems() {
      return this.ListScheduledGames.length;
    },
    paginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.ListScheduledGames.slice(start, end);
    },
    pageCount() {
      return Math.ceil(this.ListScheduledGames.length / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  methods: {
    convert(value) {
      if (!value) return "N/A";
      const date = new Date(value * 1000);
      let hours = date.getHours();
      const minutes = String(date.getMinutes()).padStart(2, "0");
      const ampm = hours >= 12 ? "PM" : "AM";
      hours = hours % 12 || 12;
      return `${String(date.getDate()).padStart(2, "0")}-${String(date.getMonth() + 1).padStart(2, "0")}-${date.getFullYear()}, ${hours}:${minutes}:${ampm}`;
    },
    OpenDialogDeleteScheduledGame(item) {
      this.StoreObj = item;
      this.DialogDeleteScheduledGame = true;
    },
    DialogDeleteScheduledGameEmit(Toggle) {
      this.DialogDeleteScheduledGame = false;
      if (Toggle === 2) {
        this.ListScheduledGamesMethod();
      }
    }
  }
};
